{
  "name": "@mirego/opencode-forra-attribution",
  "version": "0.2.0",
  "description": "OpenCode plugin that attaches Forra usage attribution headers from local git context",
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src/",
    "README.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "forra",
    "mirego",
    "opencode",
    "plugin",
    "git",
    "attribution"
  ],
  "license": "ISC",
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.18.29",
    "@opencode/plugin": "^2.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.29",
    "@opencode/plugin": "2.0.28",
    "@types/node": "^26.1.2",
    "typescript": "^5.8.2",
    "vitest": "^4.1.5"
  },
  "overrides": {
    "source-map-js": "1.2.2"
  },
  "scripts": {
    "test": "vitest run",
    "test:unit": "vitest run",
    "test:watch": "vitest",
    "type-check": "tsc --noEmit"
  }
}
